//! ActionTimer plugin: scripted sequences of actions with waits
//! (`ActionList1=Act1 | Wait 100 | Repeat Act2, 50, 4`). The measure is a
//! small state machine polled by the skin (`poll_timers`), which also asks
//! how long until the next step (`next_wakeup`) so the app can sleep exactly.

use super::{MeasureCtx, MeasureImpl};
use crate::parser::OptionReader;
use std::time::{Duration, Instant};

/// Hard cap on commands generated by one `Repeat`.
const MAX_REPEAT: i64 = 100_000;

struct Run {
    idx: usize,
    due: Instant,
}

#[derive(Default)]
pub struct ActionTimer {
    lists: Vec<Vec<String>>,
    runs: Vec<Option<Run>>,
    ignore_warnings: bool,
    log: Vec<String>,
}

impl ActionTimer {
    pub fn new() -> ActionTimer {
        ActionTimer::default()
    }

    fn warn(&mut self, msg: String) {
        if !self.ignore_warnings {
            self.log.push(msg);
        }
    }
}

fn wait_ms(cmd: &str) -> Option<u64> {
    let t = cmd.trim_start();
    if t.len() >= 5 && t.is_char_boundary(5) && t[..5].eq_ignore_ascii_case("WAIT ") {
        Some(crate::numparse::parse_i32_prefix(t[5..].trim()).unwrap_or(0).max(0) as u64)
    } else {
        None
    }
}

fn atoi(s: &str) -> i64 {
    crate::numparse::parse_i32_prefix(s.trim()).unwrap_or(0) as i64
}

impl MeasureImpl for ActionTimer {
    fn read_options(&mut self, opt: &OptionReader) {
        let raw = opt.without_sections();
        let expand = |s: &str| match opt.sv {
            Some(sv) => opt.parser.replace_section_variables(s, sv),
            None => s.to_string(),
        };
        let mut lists = Vec::new();
        let mut n = 1;
        loop {
            let action = raw.string(&format!("ActionList{n}"), "");
            if action.trim().is_empty() || n > 1000 {
                break;
            }
            n += 1;
            let mut tokens: Vec<String> = action.split('|').map(|t| t.trim().to_string()).collect();
            let mut i = 0;
            while i < tokens.len() {
                let t = tokens[i].clone();
                let upper = t.to_ascii_uppercase();
                if upper.starts_with("REPEAT ") {
                    let parts: Vec<&str> = t[7..].splitn(3, ',').map(str::trim).collect();
                    if let [name, wait, count] = parts[..] {
                        if !name.is_empty() && !wait.is_empty() && !count.is_empty() {
                            tokens.remove(i);
                            let wait = expand(wait);
                            let count = atoi(&expand(count)).min(MAX_REPEAT);
                            let action = raw.string(name, "[]");
                            let size = count * 2 - 1;
                            if size <= 0 {
                                continue;
                            }
                            for j in 0..size as usize {
                                tokens.insert(i + j, if j % 2 == 0 { action.clone() } else { format!("Wait {}", wait.trim()) });
                            }
                            i += size as usize;
                            continue;
                        }
                    }
                    // Malformed Repeat: keep the text as a (harmless) command.
                } else if upper.starts_with("WAIT ") {
                    tokens[i] = expand(&t);
                } else {
                    tokens[i] = raw.string(&t, "[]");
                }
                i += 1;
            }
            lists.push(tokens);
        }
        self.lists = lists;
        self.runs.resize_with(self.lists.len(), || None);
        self.runs.truncate(self.lists.len());
        self.ignore_warnings = opt.bool("IgnoreWarnings", false);
    }

    fn update(&mut self, _ctx: &mut MeasureCtx) -> f64 {
        0.0
    }

    fn command(&mut self, args: &str) {
        let a = args.trim_start();
        let up = a.to_ascii_uppercase();
        if up.starts_with("EXECUTE") {
            let n = atoi(&a[7..]);
            let i = (n - 1).max(-1);
            if n >= 1 && (i as usize) < self.lists.len() {
                let i = i as usize;
                if self.runs[i].is_none() {
                    self.runs[i] = Some(Run { idx: 0, due: Instant::now() });
                } else {
                    self.warn(format!("'ActionList{n}' is currently running"));
                }
            } else {
                self.warn(format!("Invalid index '{n}'"));
            }
        } else if up.starts_with("STOP") {
            let n = atoi(&a[4..]);
            if n >= 1 && (n as usize) <= self.lists.len() {
                self.runs[n as usize - 1] = None;
            } else {
                self.warn(format!("Invalid index '{n}'"));
            }
        } else {
            self.log.push(format!("Unknown command: {a}"));
        }
    }

    fn poll_timers(&mut self, now: Instant) -> Vec<String> {
        let mut out = Vec::new();
        for (i, slot) in self.runs.iter_mut().enumerate() {
            let Some(run) = slot else { continue };
            let list = &self.lists[i];
            while run.idx < list.len() && run.due <= now {
                let cmd = &list[run.idx];
                match wait_ms(cmd) {
                    Some(ms) => run.due += Duration::from_millis(ms),
                    None => out.push(cmd.clone()),
                }
                run.idx += 1;
            }
            if run.idx >= list.len() {
                *slot = None;
            }
        }
        out
    }

    fn next_wakeup(&self, now: Instant) -> Option<Duration> {
        self.runs.iter().flatten().map(|r| r.due.saturating_duration_since(now)).min()
    }

    fn take_log(&mut self) -> Vec<String> {
        std::mem::take(&mut self.log)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::measures::testutil::skin;

    fn make(ini: &str) -> ActionTimer {
        let s = skin(ini);
        let mut m = ActionTimer::new();
        m.read_options(&OptionReader { parser: &s.parser, section: "M", sv: None });
        m
    }

    const INI: &str = "[M]\nMeasure=Plugin\nPlugin=ActionTimer\nActionList1=Act1 | Wait 100 | Act2 | Repeat Act3, 50, 3\n\
        ActionList2=Act2 | Wait 10\nAct1=[!Log a1]\nAct2=[!Log a2]\nAct3=[!Log a3]\n";

    #[test]
    fn parses_lists_with_repeat() {
        let m = make(INI);
        assert_eq!(m.lists.len(), 2);
        assert_eq!(
            m.lists[0],
            ["[!Log a1]", "Wait 100", "[!Log a2]", "[!Log a3]", "Wait 50", "[!Log a3]", "Wait 50", "[!Log a3]"]
        );
        assert_eq!(m.lists[1], ["[!Log a2]", "Wait 10"]);
    }

    #[test]
    fn runs_in_order_with_waits_and_can_stop() {
        let mut m = make(INI);
        let t0 = Instant::now();
        assert!(m.next_wakeup(t0).is_none());
        m.command("Execute 1");
        let start = m.runs[0].as_ref().unwrap().due;
        assert_eq!(m.poll_timers(start), ["[!Log a1]"]);
        assert!(m.poll_timers(start + Duration::from_millis(99)).is_empty());
        assert_eq!(m.next_wakeup(start + Duration::from_millis(60)), Some(Duration::from_millis(40)));
        assert_eq!(m.poll_timers(start + Duration::from_millis(100)), ["[!Log a2]", "[!Log a3]"]);
        // Executing a running list warns.
        m.command("Execute 1");
        assert_eq!(m.take_log(), ["'ActionList1' is currently running"]);
        assert_eq!(m.poll_timers(start + Duration::from_millis(150)), ["[!Log a3]"]);
        m.command("Stop 1");
        assert!(m.poll_timers(start + Duration::from_secs(5)).is_empty());
        assert!(m.next_wakeup(start).is_none());
        // Finishes by itself.
        m.command("Execute 2");
        let s2 = m.runs[1].as_ref().unwrap().due;
        assert_eq!(m.poll_timers(s2), ["[!Log a2]"]);
        assert!(m.poll_timers(s2 + Duration::from_millis(20)).is_empty());
        assert!(m.runs[1].is_none());
    }

    #[test]
    fn bad_input_never_panics() {
        let mut m = make("[M]\nMeasure=Plugin\nPlugin=ActionTimer\nActionList1=Repeat X, , | Repeat A,1,0 | Wait abc | Repeat B, 5, 99999999999\n");
        m.command("Execute 0");
        m.command("Execute 9");
        m.command("Stop -4");
        m.command("Execute");
        m.command("Frob");
        m.command("");
        assert!(!m.take_log().is_empty());
        m.command("Execute 1");
        let _ = m.poll_timers(Instant::now() + Duration::from_secs(1));
    }
}
